"use client";

import { useState } from "react";
import Link from "next/link";
import { supabase } from "@/lib/supabase";

export default function ForgotPasswordPage() {
  const [email, setEmail] = useState("");
  const [loading, setLoading] = useState(false);
  const [sent, setSent] = useState(false);
  const [error, setError] = useState<string | null>(null);

  async function handleSubmit(e: { preventDefault(): void }) {
    e.preventDefault();
    setLoading(true);
    setError(null);

    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset-password`,
    });

    setLoading(false);

    if (error) {
      setError(error.message);
    } else {
      setSent(true);
    }
  }

  return (
    <main className="min-h-[80vh] flex items-center justify-center px-4 py-12">
      <div className="w-full max-w-md">
        <div className="bg-white rounded-2xl shadow-xl border border-gray-100 p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-[#0F2044]">Reset your password</h1>
          </div>

          {sent ? (
            <div className="flex flex-col items-center gap-4 text-center py-2">
              <div className="text-4xl">✉️</div>
              <p className="text-lg font-semibold text-gray-900">Check your inbox</p>
              <p className="text-gray-500 text-sm">
                We sent a password reset link to <span className="font-semibold text-gray-800">{email}</span>.
              </p>
              <Link
                href="/signin"
                className="mt-2 w-full rounded-xl bg-[#0F2044] py-3 text-base font-semibold text-white text-center hover:bg-[#162d5a] transition"
              >
                Back to sign in
              </Link>
            </div>
          ) : (
            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
              <div className="flex flex-col gap-1">
                <label className="text-sm font-medium text-gray-700">Email</label>
                <input
                  type="email"
                  placeholder="you@ucsc.edu"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  required
                  className="w-full rounded-xl border-2 border-gray-200 px-4 py-3 text-base focus:border-[#0F2044] focus:outline-none transition"
                />
              </div>

              {error && <p className="text-red-500 text-sm">{error}</p>}

              <button
                type="submit"
                disabled={loading}
                className="w-full rounded-xl bg-[#F5C518] py-3 text-lg font-semibold text-[#0F2044] shadow-sm transition hover:bg-[#fde047] disabled:opacity-50 mt-1 cursor-pointer"
              >
                {loading ? "Sending…" : "Send reset link"}
              </button>

              <p className="text-center text-gray-500 text-sm mt-2">
                <Link href="/signin" className="text-[#0F2044] font-semibold hover:underline">
                  Back to sign in
                </Link>
              </p>
            </form>
          )}
        </div>
      </div>
    </main>
  );
}

import { render, screen, fireEvent, waitFor, act } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach } from "vitest";
import ResetPasswordPage from "../page";
import * as supabaseModule from "@/lib/supabase";

const mockPush = vi.fn();

// Mock Next.js useRouter to test navigation behavior
vi.mock("next/navigation", () => ({
  useRouter: () => ({ push: mockPush }),
}));

vi.mock("next/link", () => ({
  default: ({ href, children, className }: { href: string; children: React.ReactNode; className?: string }) => (
    <a href={href} className={className}>{children}</a>
  ),
}));

// Capture the auth callback so tests can fire auth events manually.
type AuthCallback = (event: string, session: unknown) => void;
let capturedCallback: AuthCallback | null = null;
const mockUnsubscribe = vi.fn();

// Mock Supabase client to test auth state changes and updateUser calls without making real API calls
vi.mock("@/lib/supabase", () => ({
  supabase: {
    auth: {
      onAuthStateChange: vi.fn((cb: AuthCallback) => {
        capturedCallback = cb;
        return { data: { subscription: { unsubscribe: mockUnsubscribe } } };
      }),
      updateUser: vi.fn(),
    },
  },
}));

// Helper function to trigger auth events in tests by calling the captured callback with the specified event name
function triggerAuthEvent(event: string) {
  act(() => { capturedCallback?.(event, null); });
}

// Test suite for the ResetPasswordPage component, covering verifying state, showing the password form on PASSWORD_RECOVERY event, validating password inputs, calling updateUser, handling errors, and unsubscribing on unmount
describe("ResetPasswordPage", () => {
  beforeEach(() => {
    capturedCallback = null;
    mockPush.mockClear();
    mockUnsubscribe.mockClear();
    vi.mocked(supabaseModule.supabase.auth.updateUser).mockResolvedValue(
      { data: { user: {} }, error: null } as Awaited<ReturnType<typeof supabaseModule.supabase.auth.updateUser>>
    );
  });

  // Test that the component shows a verifying state before the auth event fires, and does not show the password form
  it("shows a verifying state before the auth event fires", () => {
    render(<ResetPasswordPage />);
    expect(screen.getByText(/verifying reset link/i)).toBeInTheDocument();
    expect(screen.queryByPlaceholderText("Create a new password")).toBeNull();
  });

  // Test that the component shows the new password and confirm password fields when a PASSWORD_RECOVERY event is fired
  it("shows the password form after a PASSWORD_RECOVERY event", () => {
    render(<ResetPasswordPage />);
    triggerAuthEvent("PASSWORD_RECOVERY");
    expect(screen.getByPlaceholderText("Create a new password")).toBeInTheDocument();
    expect(screen.getByPlaceholderText("Repeat your new password")).toBeInTheDocument();
  });

  // Test that the component shows an error message when the new password and confirm password fields do not match, and does not call updateUser
  it("shows an error when passwords do not match", async () => {
    render(<ResetPasswordPage />);
    triggerAuthEvent("PASSWORD_RECOVERY");

    fireEvent.change(screen.getByPlaceholderText("Create a new password"), { target: { value: "password1" } });
    fireEvent.change(screen.getByPlaceholderText("Repeat your new password"), { target: { value: "password2" } });
    fireEvent.submit(screen.getByRole("button", { name: /update password/i }).closest("form")!);

    expect(screen.getByText(/passwords do not match/i)).toBeInTheDocument();
    expect(supabaseModule.supabase.auth.updateUser).not.toHaveBeenCalled();
  });

  // Test that the component shows an error message when the new password is fewer than 6 characters, and does not call updateUser
  it("shows an error when the password is fewer than 6 characters", async () => {
    render(<ResetPasswordPage />);
    triggerAuthEvent("PASSWORD_RECOVERY");

    fireEvent.change(screen.getByPlaceholderText("Create a new password"), { target: { value: "abc" } });
    fireEvent.change(screen.getByPlaceholderText("Repeat your new password"), { target: { value: "abc" } });
    fireEvent.submit(screen.getByRole("button", { name: /update password/i }).closest("form")!);

    expect(screen.getByText(/at least 6 characters/i)).toBeInTheDocument();
    expect(supabaseModule.supabase.auth.updateUser).not.toHaveBeenCalled();
  });

  // Test that the component calls updateUser with the new password and redirects to the home page on success
  it("calls updateUser with the new password and redirects on success", async () => {
    render(<ResetPasswordPage />);
    triggerAuthEvent("PASSWORD_RECOVERY");

    fireEvent.change(screen.getByPlaceholderText("Create a new password"), { target: { value: "newpass123" } });
    fireEvent.change(screen.getByPlaceholderText("Repeat your new password"), { target: { value: "newpass123" } });
    fireEvent.submit(screen.getByRole("button", { name: /update password/i }).closest("form")!);

    await waitFor(() => expect(mockPush).toHaveBeenCalledWith("/"));
    expect(supabaseModule.supabase.auth.updateUser).toHaveBeenCalledWith({ password: "newpass123" });
  });

  // Test that the component shows an error message when updateUser returns an error, and does not redirect
  it("shows an error when updateUser fails", async () => {
    vi.mocked(supabaseModule.supabase.auth.updateUser).mockResolvedValue(
      { data: { user: null }, error: { message: "Token has expired" } } as unknown as Awaited<ReturnType<typeof supabaseModule.supabase.auth.updateUser>>
    );

    render(<ResetPasswordPage />);
    triggerAuthEvent("PASSWORD_RECOVERY");

    fireEvent.change(screen.getByPlaceholderText("Create a new password"), { target: { value: "newpass123" } });
    fireEvent.change(screen.getByPlaceholderText("Repeat your new password"), { target: { value: "newpass123" } });
    fireEvent.submit(screen.getByRole("button", { name: /update password/i }).closest("form")!);

    await waitFor(() => expect(screen.getByText("Token has expired")).toBeInTheDocument());
    expect(mockPush).not.toHaveBeenCalled();
  });

  // Test that the component unsubscribes from auth state changes when it unmounts
  it("unsubscribes from onAuthStateChange on unmount", () => {
    const { unmount } = render(<ResetPasswordPage />);
    unmount();
    expect(mockUnsubscribe).toHaveBeenCalled();
  });
});

"use client";

import { useEffect, useState } from "react";
import Link from "next/link";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import { Eye, EyeOff } from "lucide-react";

export default function ResetPasswordPage() {
  const router = useRouter();
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [ready, setReady] = useState(false);

  // Supabase redirects here with a session embedded in the URL hash.
  // onAuthStateChange fires with SIGNED_IN / PASSWORD_RECOVERY once the
  // client has exchanged the token, signalling the form is safe to submit.
  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange((event) => {
      if (event === "PASSWORD_RECOVERY" || event === "SIGNED_IN") {
        setReady(true);
      }
    });
    return () => subscription.unsubscribe();
  }, []);

  async function handleSubmit(e: { preventDefault(): void }) {
    e.preventDefault();
    if (password !== confirm) {
      setError("Passwords do not match.");
      return;
    }
    if (password.length < 6) {
      setError("Password must be at least 6 characters.");
      return;
    }

    setLoading(true);
    setError(null);

    const { error } = await supabase.auth.updateUser({ password });

    setLoading(false);

    if (error) {
      setError(error.message);
    } else {
      router.push("/");
    }
  }

  if (!ready) {
    return (
      <main className="min-h-[80vh] flex items-center justify-center px-4 py-12">
        <p className="text-gray-500">Verifying reset link…</p>
      </main>
    );
  }

  return (
    <main className="min-h-[80vh] flex items-center justify-center px-4 py-12">
      <div className="w-full max-w-md">
        <div className="bg-white rounded-2xl shadow-xl border border-gray-100 p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-[#0F2044]">Choose a new password</h1>
            <p className="text-gray-500 mt-1">Enter a new password for your account.</p>
          </div>

          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium text-gray-700">New password</label>
              <div className="relative">
                <input
                  type={showPassword ? "text" : "password"}
                  placeholder="Create a new password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  className="w-full rounded-xl border-2 border-gray-200 px-4 py-3 pr-12 text-base focus:border-[#0F2044] focus:outline-none transition"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword((p) => !p)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 cursor-pointer"
                >
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
            </div>

            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium text-gray-700">Confirm password</label>
              <input
                type={showPassword ? "text" : "password"}
                placeholder="Repeat your new password"
                value={confirm}
                onChange={(e) => setConfirm(e.target.value)}
                required
                className="w-full rounded-xl border-2 border-gray-200 px-4 py-3 text-base focus:border-[#0F2044] focus:outline-none transition"
              />
            </div>

            {error && <p className="text-red-500 text-sm">{error}</p>}

            <button
              type="submit"
              disabled={loading}
              className="w-full rounded-xl bg-[#F5C518] py-3 text-lg font-semibold text-[#0F2044] shadow-sm transition hover:bg-[#fde047] disabled:opacity-50 mt-1 cursor-pointer"
            >
              {loading ? "Updating…" : "Update password"}
            </button>
          </form>
        </div>
      </div>
    </main>
  );
}

