"use client";

import { useState } from "react";
import Link from "next/link";
import { supabase } from "@/lib/supabase";
import { Eye, EyeOff, Mail } from "lucide-react";

export default function SignUpPage() {
  const [username, setUsername] = useState("");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [verified, setVerified] = useState(false);

  async function handleSubmit(e: { preventDefault(): void }) {
    e.preventDefault();
    setError(null);

    if (!email.endsWith("@ucsc.edu")) {
      setError("Only @ucsc.edu email addresses are allowed.");
      return;
    }

    setLoading(true);

    const { data, error } = await supabase.auth.signUp({
      email,
      password,
      options: {
        data: { username },
      },
    });

    setLoading(false);

    if (error) {
      setError(error.message);
    } else {
      setVerified(true);
    }
  }

  if (verified) {
    return (
      <main className="min-h-[80vh] flex items-center justify-center px-4 py-12">
        <div className="w-full max-w-md">
          <div className="bg-white rounded-2xl shadow-xl border border-gray-100 p-8 flex flex-col items-center gap-4 text-center">
            <div className="w-16 h-16 rounded-full bg-[#0F2044]/10 flex items-center justify-center">
              <Mail size={32} className="text-[#0F2044]" />
            </div>
            <h1 className="text-2xl font-bold text-gray-900">Check your email</h1>
            <p className="text-gray-500">
              We sent a verification link to <span className="font-semibold text-gray-800">{email}</span>. Click the link in that email to activate your account.
            </p>
            <p className="text-gray-400 text-sm">Didn&apos;t get it? Check your spam folder.</p>
            <Link href="/signin" className="mt-2 w-full rounded-xl bg-[#0F2044] py-3 text-lg font-semibold text-white hover:bg-[#162d5a] transition text-center">
              Go to sign in
            </Link>
          </div>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-[80vh] flex items-center justify-center px-4 py-12">
      <div className="w-full max-w-md">
        <div className="bg-white rounded-2xl shadow-xl border border-gray-100 p-8">
          <div className="text-center mb-8">
            <h1 className="text-3xl font-bold text-[#0F2044]">Create an account</h1>
            <p className="text-gray-500 mt-1">Join SlugMarket with your UCSC email</p>
          </div>

          <form onSubmit={handleSubmit} className="flex flex-col gap-4">
            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium text-gray-700">Username</label>
              <input
                type="text"
                name="username"
                placeholder="slugger123"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
                required
                className="w-full rounded-xl border-2 border-gray-200 px-4 py-3 text-base focus:border-[#0F2044] focus:outline-none transition"
              />
            </div>

            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium text-gray-700">Email</label>
              <input
                type="email"
                name="email"
                placeholder="you@ucsc.edu"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                required
                className="w-full rounded-xl border-2 border-gray-200 px-4 py-3 text-base focus:border-[#0F2044] focus:outline-none transition"
              />
            </div>

            <div className="flex flex-col gap-1">
              <label className="text-sm font-medium text-gray-700">Password</label>
              <div className="relative">
                <input
                  type={showPassword ? "text" : "password"}
                  name="password"
                  placeholder="Create a password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  className="w-full rounded-xl border-2 border-gray-200 px-4 py-3 pr-12 text-base focus:border-[#0F2044] focus:outline-none transition"
                />
                <button
                  type="button"
                  onClick={() => setShowPassword((p) => !p)}
                  className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600 cursor-pointer"
                >
                  {showPassword ? <EyeOff size={20} /> : <Eye size={20} />}
                </button>
              </div>
            </div>

            {error && <p className="text-red-500 text-sm">{error}</p>}

            <button
              type="submit"
              disabled={loading}
              className="w-full rounded-xl bg-[#F5C518] py-3 text-lg font-semibold text-[#0F2044] shadow-sm transition hover:bg-[#fde047] disabled:opacity-50 mt-1 cursor-pointer"
            >
              {loading ? "Creating account…" : "Create Account"}
            </button>
          </form>

          <p className="text-center text-gray-500 text-sm mt-6">
            Already have an account?{" "}
            <Link href="/signin" className="text-[#0F2044] font-semibold hover:underline">
              Sign in
            </Link>
          </p>
        </div>
      </div>
    </main>
  );
}

import { supabase } from "@/lib/supabase";
import { fetchProductsBySellerId, fetchSoldListingsBySellerId } from "@/lib/fetchProducts";
import ProfileTabs from "../../components/ProfileTabs";
import AvatarUpload from "../../components/AvatarUpload";
import EditProfile from "../../components/EditProfile";
import { Star } from "lucide-react";

// ProfilePage component is responsible for rendering the user's profile page.
// It retrieves the username from the URL parameters, looks up the user's profile information from the database, and fetches their active and sold listings.
// The page displays the user's avatar, username, and tabs for their active and sold listings. 
// If the user is not found, it shows a "User not found" message.
export default async function ProfilePage({
  params,
}: {
  params: Promise<{ username: string }>;
}) {
  const { username } = await params;

  // Look up the user's ID from the profiles table
  const { data: profile } = await supabase
    .from("profiles")
    .select("id, avatar_url, bio, college")
    .eq("username", username)
    .single();

  // Fetch active and sold listings if the profile exists
  const [listings, soldListings] = profile
    ? await Promise.all([
        fetchProductsBySellerId(profile.id),
        fetchSoldListingsBySellerId(profile.id),
      ])
    : [[], []];

  // Batch-fetch buyer usernames for sold listings that have a buyer_id
  const buyerIds = (soldListings ?? [])
    .map((l) => l.buyer_id)
    .filter((id): id is string => !!id);

  let buyerUsernames: Record<string, string> = {};
  if (buyerIds.length > 0) {
    const { data: buyers } = await supabase
      .from("profiles")
      .select("id, username")
      .in("id", buyerIds);
    for (const b of buyers ?? []) {
      buyerUsernames[b.id] = b.username;
    }
  }

  // Get average review rating for profile
  // Fetch average rating for this user
  let averageRating: number | null = null;

  if (profile) {
    const { data: ratingRows } = await supabase
      .from("reviews")
      .select("rating")
      .eq("reviewed_user_id", profile.id);

    if (ratingRows && ratingRows.length > 0) {
      const sum = ratingRows.reduce((acc, r) => acc + r.rating, 0);
      averageRating = sum / ratingRows.length;
    }
  }


 // Render the profile page with the user's listings and sold items
  return (
    <main className="w-full max-w-4xl mx-auto px-6 py-12">
      {/* Profile card */}
      <div className="rounded-2xl border border-gray-100 bg-white shadow-sm overflow-hidden mb-8">
        {/* Banner */}
        <div className="h-24 bg-[#0F2044]" />

        {/* Avatar + info */}
        <div className="px-6 pb-6">
          <div className="-mt-12 mb-3">
            <AvatarUpload
              profileId={profile?.id ?? ""}
              username={username}
              avatarUrl={profile?.avatar_url ?? null}
            />
          </div>

          <h1 className="text-2xl font-bold text-gray-900">@{username}</h1>

          {averageRating !== null && (
            <div className="flex items-center gap-1 mt-1 mb-1">
              {Array.from({ length: 5 }).map((_, i) => (
                <Star
                  key={i}
                  size={14}
                  className={i < Math.round(averageRating!) ? "fill-[#F5C518] text-[#F5C518]" : "fill-gray-200 text-gray-200"}
                />
              ))}
              <span className="text-sm text-gray-500 ml-1">{averageRating.toFixed(1)}</span>
            </div>
          )}

          <EditProfile profileId={profile?.id ?? ""} initialBio={profile?.bio ?? null} initialCollege={profile?.college ?? null} />
        </div>
      </div>

      {!profile ? (
        <p className="text-gray-400 italic">User not found.</p>
      ) : (
        <ProfileTabs listings={listings ?? []} soldListings={soldListings ?? []} profileId={profile.id} buyerUsernames={buyerUsernames} />
      )}
    </main>
  );
}

"use client";

import { useEffect, useState } from "react";
import ListingCard from "@/app/components/ListingCard";
import { fetchBookmarkedProducts } from "@/lib/fetchProducts";
import { useAuth } from "@/app/components/AuthProvider";
import { Listing } from "@/lib/types";

// This page displays the user's bookmarked items. 
// It fetches the bookmarked products from the database when the component mounts and handles loading states and user authentication. 
// If the user is not signed in, it prompts them to sign in to view their bookmarks.
export default function BookmarksPage() {
  const { user, loading } = useAuth();
  const [products, setProducts] = useState<Listing[]>([]);
  const [pageLoading, setPageLoading] = useState(true);

  useEffect(() => {
    // Function to load bookmarked products for the authenticated user.
    async function loadBookmarks() {
      if (!user) {
        setProducts([]);
        setPageLoading(false);
        return;
      }

      try {
        const bookmarkedProducts = await fetchBookmarkedProducts(user.id);
        setProducts(bookmarkedProducts);
      } catch (error) {
        console.error("Error loading bookmarked products:", error);
        setProducts([]);
      } finally {
        setPageLoading(false);
      }
    }

    // Load bookmarks once the user is authenticated and not loading.
    if (!loading) {
      loadBookmarks();
    }
  }, [user, loading]);

  if (loading || pageLoading) {
    return (
      <main className="max-w-6xl mx-auto px-6 py-12">
        <h1 className="text-4xl font-bold mb-4">Bookmarked Items</h1>
        <p className="text-gray-600">Loading...</p>
      </main>
    );
  }

// If the user is not authenticated, prompt them to sign in to view their bookmarks.
  if (!user) {
    return (
      <main className="max-w-6xl mx-auto px-6 py-12">
        <h1 className="text-4xl font-bold mb-4">Bookmarked Items</h1>
        <p className="text-gray-600">Please sign in to view your bookmarked items.</p>
      </main>
    );
  }

  return (
    <main className="max-w-6xl mx-auto px-6 py-12">
      <h1 className="text-4xl font-bold mb-6">Bookmarked Items</h1>

      {products.length === 0 ? (
        <div className="rounded-xl border border-dashed border-gray-300 p-10 text-center text-gray-500">
          You have no bookmarked items yet.
        </div>
      ) : (
        <div className="grid grid-cols-1 gap-6 min-[770px]:grid-cols-2 lg:grid-cols-4">
          {products.map((listing, index) => (
            <ListingCard key={listing.id} listing={listing} priority={index === 0} />
          ))}
        </div>
      )}
    </main>
  );
}

import { render, screen, fireEvent, waitFor } from "@testing-library/react";
import { describe, it, expect, vi, beforeEach } from "vitest";
import MessagesPage from "../page";
import * as AuthProvider from "@/app/components/AuthProvider";
import type { Conversation, Message } from "@/lib/types";

const mockReplace = vi.hoisted(() => vi.fn());
const mockSearchParams = vi.hoisted(() => vi.fn(() => new URLSearchParams()));

// Conversations query chain: .from("conversations").select().or().order()
const mockConvosOrder = vi.hoisted(() => vi.fn());
const mockConvosOr = vi.hoisted(() => vi.fn(() => ({ order: mockConvosOrder })));
const mockConvosSelect = vi.hoisted(() => vi.fn(() => ({ or: mockConvosOr })));

// Messages fetch chain: .from("messages").select().eq().order()
const mockMsgsOrder = vi.hoisted(() => vi.fn());
const mockMsgsSelectEq = vi.hoisted(() => vi.fn(() => ({ order: mockMsgsOrder })));
const mockMsgsSelect = vi.hoisted(() => vi.fn(() => ({ eq: mockMsgsSelectEq })));

// Messages read-update chain: .from("messages").update().eq().neq().is()
const mockMsgsIs = vi.hoisted(() => vi.fn());
const mockMsgsNeq = vi.hoisted(() => vi.fn(() => ({ is: mockMsgsIs })));
const mockMsgsUpdateEq = vi.hoisted(() => vi.fn(() => ({ neq: mockMsgsNeq })));
const mockMsgsUpdate = vi.hoisted(() => vi.fn(() => ({ eq: mockMsgsUpdateEq })));

// Messages insert
const mockMsgsInsert = vi.hoisted(() => vi.fn());

// Offers update chain: .from("offers").update().eq().select().single()
const mockOffersSingle = vi.hoisted(() => vi.fn());
const mockOffersSelect = vi.hoisted(() => vi.fn(() => ({ single: mockOffersSingle })));
const mockOffersEq = vi.hoisted(() => vi.fn(() => ({ select: mockOffersSelect })));
const mockOffersUpdate = vi.hoisted(() => vi.fn(() => ({ eq: mockOffersEq })));

// Routes from() calls by table name
const mockFrom = vi.hoisted(() => vi.fn((table: string) => {
  if (table === "conversations") return { select: mockConvosSelect };
  if (table === "messages") return { select: mockMsgsSelect, update: mockMsgsUpdate, insert: mockMsgsInsert };
  if (table === "offers") return { update: mockOffersUpdate };
  return {};
}));

// Realtime channel mocks
const mockSubscribe = vi.hoisted(() => vi.fn());
const mockOn = vi.hoisted(() => vi.fn());
const mockChannelObj = vi.hoisted(() => ({ on: mockOn, subscribe: mockSubscribe }));
const mockChannel = vi.hoisted(() => vi.fn(() => mockChannelObj));
const mockRemoveChannel = vi.hoisted(() => vi.fn());

vi.mock("next/navigation", () => ({
  useRouter: () => ({ replace: mockReplace }),
  useSearchParams: mockSearchParams,
}));

vi.mock("@/app/components/AuthProvider");

vi.mock("@/lib/supabase", () => ({
  supabase: {
    from: mockFrom,
    channel: mockChannel,
    removeChannel: mockRemoveChannel,
  },
}));

vi.mock("@/app/components/ConversationList", () => ({
  default: ({ conversations, loadingConvos, onSelect }: {
    conversations: Conversation[];
    loadingConvos: boolean;
    onSelect: (id: string) => void;
  }) => (
    <div data-testid="conversation-list">
      {loadingConvos && <span>Loading conversations…</span>}
      {conversations.map((c) => (
        <button key={c.id} onClick={() => onSelect(c.id)}>convo-{c.id}</button>
