}));

vi.mock("@/app/components/MessageThread", () => ({
  default: ({ messages, input, onInputChange, onSend, onBack, onOfferStatusChange }: {
    messages: Message[];
    input: string;
    onInputChange: (val: string) => void;
    onSend: () => void;
    onBack: () => void;
    onOfferStatusChange: (offerId: string, status: "accepted" | "declined") => void;
