import { NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";

// This API route handles POST requests to filter products based on category, price range, and condition. 
// It constructs a query based on the provided filters and returns the matching products from the database.
export async function POST(req: Request) {
  const { category, minPrice, maxPrice, condition} = await req.json();

  let query = supabase.from("product_listings").select("*").eq("sold", false);

  if (category) query = query.eq("category", category);
  if (condition) query = query.eq("condition", condition)
  if (minPrice) query = query.gte("price", Number(minPrice));
  if (maxPrice) query = query.lte("price", Number(maxPrice));

  const { data, error } = await query.order("created_at", { ascending: false });

  if (error) return NextResponse.json({ error }, { status: 500 });

  return NextResponse.json({ products: data });
}

import { NextRequest, NextResponse } from "next/server";
import { supabase } from "@/lib/supabase";

// Supabase redirects here after email confirmation or OAuth login.
// This route exchanges the one-time `code` in the URL for a real session.
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const code = searchParams.get("code");

  if (code) {
    await supabase.auth.exchangeCodeForSession(code);
  }

  // Redirect to home after successful auth
  return NextResponse.redirect(new URL("/", request.url));
}

"use client";

import React, { createContext, useContext, useEffect, useMemo, useState } from "react";
import type { Session, User } from "@supabase/supabase-js"
import { supabase } from "@/lib/supabase"

// This file provides an AuthProvider component that manages user authentication state using Supabase.
// It also exports a useAuth hook for easy access to auth state in any component.

type AuthContextValue = {
    user: User | null;
    session: Session | null;
    loading: boolean;
    avatarUrl: string | null;
    setAvatarUrl: (url: string | null) => void;
}

const AuthContext = createContext<AuthContextValue | undefined>(undefined);

// The AuthProvider component initializes the authentication state by checking for an existing session and listening for auth state changes. 
// It also fetches the user's avatar URL from the profiles table whenever the user changes. 
// The context value includes the user, session, loading state, avatar URL, and a function to update the avatar URL.
export default function AuthProvider({ children }: { children: React.ReactNode }) {
    const [session, setSession] = useState<Session | null>(null)
    const [user, setUser] = useState<User | null>(null)
    const [loading, setLoading] = useState(true)
    const [avatarUrl, setAvatarUrl] = useState<string | null>(null)

    useEffect(() => {
        let mounted = true

        // initialize session
        supabase.auth.getSession()
        .then(({ data, error }) => {
            if (!mounted) return
            if (error) console.error("getSession error:", error.message)

            setSession(data.session ?? null)
            setUser(data.session?.user ?? null)
            setLoading(false)
        })

        // listen for changes like sign in/out or token refresh
        const { data: listener } = supabase.auth.onAuthStateChange((event, nextSession) => {
            setSession(nextSession)
            setUser(nextSession?.user ?? null)
            setLoading(false)
            if (!nextSession?.user) setAvatarUrl(null)
        })

        return () => {
            mounted = false
            listener.subscription.unsubscribe()
        }
    }, [])

    // Fetch avatar_url from profiles whenever the user changes
    useEffect(() => {
        if (!user) return
        supabase
            .from("profiles")
            .select("avatar_url")
            .eq("id", user.id)
            .single()
            .then(({ data }) => setAvatarUrl(data?.avatar_url ?? null))
    }, [user?.id])

    const value = useMemo<AuthContextValue>(
        () => ({ user, session, loading, avatarUrl, setAvatarUrl }),
        [user, session, loading, avatarUrl]
    )

    return <AuthContext.Provider value={value}>
        {children}
    </AuthContext.Provider>
}

// custom hook for getting context {user, session, loading}
export function useAuth() {
    const context = useContext(AuthContext)
    if (!context) {
        throw new Error("useAuth must be used within AuthProvider")
    }
    return context
}

"use client";

import { useEffect, useRef, useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import { useAuth } from "./AuthProvider";

interface AvatarUploadProps {
  profileId: string;
  username: string;
  avatarUrl: string | null;
}

export default function AvatarUpload({ profileId, username, avatarUrl }: AvatarUploadProps) {
  const { user, setAvatarUrl } = useAuth();
  const router = useRouter();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [uploading, setUploading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [currentUrl, setCurrentUrl] = useState<string | null>(avatarUrl);

  // Sync when server re-renders with updated avatarUrl (after router.refresh())
  useEffect(() => {
    setCurrentUrl(avatarUrl);
  }, [avatarUrl]);

  const isOwner = user?.id === profileId;

  // Handle file selection and upload process
  async function handleFileChange(e: React.ChangeEvent<HTMLInputElement>) {
    const file = e.target.files?.[0];
    if (!file || !user) return;

    // Create a temporary URL for immediate preview while uploading
    const blobUrl = URL.createObjectURL(file);
    setCurrentUrl(blobUrl);
    setUploading(true);
    setError(null);

    // Upload to Supabase Storage and update profile with new avatar URL
    try {
      const storagePath = `${profileId}/avatar`;

      const { error: uploadError } = await supabase.storage
        .from("avatars")
        .upload(storagePath, file, { upsert: true });

      if (uploadError) throw new Error(uploadError.message);

      const { data: { publicUrl } } = supabase.storage
        .from("avatars")
        .getPublicUrl(storagePath);

      // The storage path is stable (upsert overwrites the same file), so the
      // public URL never changes. Persist a cache-busted URL so that after a
      // refresh the browser fetches the new image instead of the cached one.
      const timedUrl = `${publicUrl}?t=${Date.now()}`;

      const { error: updateError } = await supabase
        .from("profiles")
        .update({ avatar_url: timedUrl })
        .eq("id", profileId);

      if (updateError) throw new Error(updateError.message);

      // Only update UI and context after both storage upload and DB write succeed
      URL.revokeObjectURL(blobUrl);
      setCurrentUrl(timedUrl);
      setAvatarUrl(timedUrl);

      router.refresh();
    } catch (err: unknown) {
      const message = err instanceof Error ? err.message : "Upload failed";
      console.error("Avatar upload error:", message);
      setError(message);
      setCurrentUrl(avatarUrl);
    } finally {
      setUploading(false);
      e.target.value = "";
    }
  }

  return (
    <div className="relative w-24 h-24 shrink-0">
      <div className="w-24 h-24 rounded-full bg-[#F5C518] border-4 border-white flex items-center justify-center text-3xl font-bold text-[#0F2044] overflow-hidden shadow-sm">
        {currentUrl ? (
          <img
            src={currentUrl}
            alt={`${username}'s avatar`}
            className="w-full h-full object-cover"
          />
        ) : (
          username[0].toUpperCase()
        )}
      </div>

      {isOwner && (
        <>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={uploading}
            title="Change profile picture"
            className="absolute bottom-0 right-0 w-7 h-7 rounded-full bg-[#0F2044] border-2 border-white flex items-center justify-center shadow hover:bg-[#162d5a] transition-colors disabled:opacity-50 cursor-pointer"
          >
            <span className="text-white font-bold text-base leading-none">+</span>
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept="image/*"
            onChange={handleFileChange}
            className="hidden"
          />
        </>
      )}

      {uploading && (
        <div className="absolute inset-0 rounded-full bg-black/30 flex items-center justify-center border-4 border-white">
          <span className="text-white text-xs">…</span>
        </div>
      )}

      {error && (
        <p className="absolute top-full mt-1 left-0 text-xs text-red-500 whitespace-nowrap">
          {error}
        </p>
      )}
    </div>
  );
}

