"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import { useAuth } from "./AuthProvider";
import { revalidateListings } from "@/app/actions/listings";
import { Trash2 } from "lucide-react";

type DeleteButtonProps = {
    productId: string;
    sellerId: string;
    imageUrls: string[];
    className?: string;
};

// This component renders a delete button for a product listing. It checks if the current user is the seller before rendering.
export default function DeleteButton({ productId, sellerId, imageUrls, className }: DeleteButtonProps) {
    const { user } = useAuth();
    const [loading, setLoading] = useState(false);
    const [showModal, setShowModal] = useState(false);
    const router = useRouter();

    if (user?.id !== sellerId) return null;

    async function handleDelete() {
        setLoading(true);

        // Extract storage paths from public URLs and delete from storage
        const BUCKET = "listing-images";
        const marker = `/${BUCKET}/`;
        const filePaths = imageUrls
            .map((url) => {
                const idx = url.indexOf(marker);
                if (idx === -1) return null;
                const path = url.slice(idx + marker.length).split("?")[0];
                return path || null;
            })
            .filter((p): p is string => p !== null);

        if (filePaths.length > 0) {
            const { error: storageError } = await supabase.storage.from(BUCKET).remove(filePaths);
            if (storageError) console.error("[DeleteButton] storage removal error:", storageError);
        }

        const { error } = await supabase.from("product_listings").delete().eq("id", productId);
        if (error) {
            setLoading(false);
            setShowModal(false);
            return;
        }
        await revalidateListings();
        router.push("/");
    }

    return (
        <>
            <button
                onClick={() => setShowModal(true)}
                className={className ?? "flex items-center justify-center gap-2 w-full rounded-xl border-2 border-gray-200 bg-white px-6 py-3 text-sm font-semibold text-gray-500 transition hover:border-red-300 hover:text-red-500 cursor-pointer"}
            >
                <Trash2 size={16} />
                Delete Listing
            </button>

            {showModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
                    <div className="bg-white rounded-2xl p-8 max-w-sm w-full mx-4 flex flex-col gap-6 shadow-xl">
                        <div>
                            <h2 className="text-2xl font-bold text-gray-900 mb-2">Delete listing?</h2>
                            <p className="text-gray-600">This action cannot be undone. The listing will be permanently removed.</p>
                        </div>
                        <div className="flex flex-col gap-3">
                            <button
                                onClick={handleDelete}
                                disabled={loading}
                                className="w-full rounded-xl bg-red-500 py-3 text-lg font-semibold text-white transition hover:bg-red-600 disabled:opacity-50 cursor-pointer"
                            >
                                {loading ? "Deleting..." : "Yes, delete it"}
                            </button>
                            <button
                                onClick={() => setShowModal(false)}
                                disabled={loading}
                                className="w-full rounded-xl border-2 border-gray-300 bg-white py-3 text-lg font-semibold text-gray-700 transition hover:bg-gray-50 disabled:opacity-50 cursor-pointer"
                            >
                                Cancel
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </>
    );
}

"use client";

import { useEffect, useRef, useState } from "react";
import { ChevronDown, Check } from "lucide-react";

export type Option = { label: string; value: string };

const defaultTriggerClass =
  "w-full flex items-center justify-between rounded-xl border-2 border-gray-200 bg-white px-4 py-2.5 text-sm transition hover:border-gray-300 focus:outline-none focus:border-[#0F2044] cursor-pointer";

export default function Dropdown({
  options,
  value,
  onSelect,
  placeholder,
  triggerClassName = defaultTriggerClass,
  ariaLabelledby,
}: {
  options: Option[];
  value: string;
  onSelect: (value: string) => void;
  // Shown in the trigger when nothing is selected. Without it, the first option's label is used.
  placeholder?: string;
  triggerClassName?: string;
  // id of an external <label> to associate with the trigger button for accessibility.
  ariaLabelledby?: string;
}) {
  const [open, setOpen] = useState(false);
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    function handleClickOutside(e: MouseEvent) {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    }
    document.addEventListener("mousedown", handleClickOutside);
    return () => document.removeEventListener("mousedown", handleClickOutside);
  }, []);

  const match = options.find((o) => o.value === value);
  const selectedLabel = value
    ? match?.label ?? placeholder ?? ""
    : placeholder ?? match?.label ?? options[0]?.label ?? "";

  return (
    <div className="relative" ref={ref}>
      <button type="button" aria-labelledby={ariaLabelledby} onClick={() => setOpen((v) => !v)} className={triggerClassName}>
        <span className={value ? "text-gray-900" : "text-gray-400"}>{selectedLabel}</span>
        <ChevronDown size={16} className={`text-gray-400 transition-transform ${open ? "rotate-180" : ""}`} />
      </button>
      {open && (
        <ul className="absolute z-20 mt-1 w-full bg-white border border-gray-200 rounded-xl shadow-lg overflow-hidden max-h-56 overflow-y-auto">
          {options.map((opt) => (
            <li key={opt.value || "none"}>
              <button
                type="button"
                onClick={() => { onSelect(opt.value); setOpen(false); }}
                className="w-full flex items-center gap-2 px-4 py-2.5 text-sm text-gray-800 hover:bg-[#0F2044]/5 transition cursor-pointer"
              >
                <span className="flex-1 text-left">{opt.label}</span>
                {value === opt.value && <Check size={14} className="text-[#0F2044] shrink-0" />}
              </button>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

