            </div>
        </>
    )
}

"use client";

import React, { useEffect, useState } from "react";
import { usePathname, useRouter } from "next/navigation";
import { ArrowRight } from "lucide-react";

// This component renders a search bar in the navigation that allows users to search for listings. 
// It manages the search query state, handles form submission to navigate to the search results page, and clears the search input when navigating to a different page.
export default function NavSearchBar() {
    const router = useRouter()
    const pathname = usePathname()
    const [q, setQ] = useState("")

    // clear searchbar when going to different page
    useEffect(() => {
        setQ("")
    }, [pathname])

    function onSubmit(e: React.FormEvent) {
        e.preventDefault()
        const query = q.trim()
        if (!query) {
            setQ("")
            return
        }

        router.push(`/search?q=${encodeURIComponent(query)}`)
        setQ("") // clear searchbar after submitting    
    }

    return (
        <form onSubmit={onSubmit} className="flex items-center w-full">
            <div className="relative w-full">
                <input
                    type="search"
                    value={q}
                    onChange={(e) => setQ(e.target.value)}
                    placeholder="Search listings…"
                    className="w-full rounded-full bg-gray-100 pl-4 pr-10 py-2 text-sm text-gray-900 placeholder:text-gray-400 outline-none focus:bg-white focus:ring-2 focus:ring-[#0F2044]/20 transition"
                />
                {q.trim().length > 0 && (
                    <button
                        type="submit"
                        aria-label="Submit search"
                        className="absolute right-2 top-1/2 -translate-y-1/2 flex items-center justify-center h-6 w-6 rounded-full bg-[#0F2044] text-white transition hover:bg-[#162d5a] cursor-pointer"
                    >
                        <ArrowRight size={13} />
                    </button>
                )}
            </div>
        </form>
      );
}

﻿"use client";

import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import { useAuth } from "./AuthProvider";
import { supabase } from "@/lib/supabase";
import NavSearchBar from "./NavSearchBar";
import NotificationBell from "./NotificationBell";
import useUnreadMessageCount from "@/lib/useUnreadMessageCount"

import {
  House,
  Search,
  PlusSquare,
  Bookmark,
  MessageCircle,
  User,
  LogOut,
} from "lucide-react";

const baseLinks = [
  { href: "/", label: "Home", icon: House },
  { href: "/search", label: "Search", icon: Search },
];

const signedOutLinks = [
  { href: "/signin", label: "Sign In", icon: User },
];

// Navbar component that displays navigation links based on the user's authentication state. It also includes a search bar and a sign out button for authenticated users.
export default function Navbar() {
  const pathname = usePathname();
  const router = useRouter();
  const { user, loading, avatarUrl } = useAuth();
  const unreadMessages = useUnreadMessageCount(user?.id)
  const hasUnreadMessages = unreadMessages > 0

  function getLinkClasses(href: string) {
    const isActive =
      href === "/"
        ? pathname === "/"
        : pathname === href || pathname.startsWith(href + "/");

    return isActive
      ? "text-blue-600 font-semibold"
      : "text-gray-700 hover:text-blue-600";
  }

  async function handleSignOut() {
    const { error } = await supabase.auth.signOut();
    if (error) {
      console.error("sign out error:", error.message);
    }
    router.replace("/");
    router.refresh();
  }

  if (loading) return null;

  const username = user?.user_metadata?.username;

  const signedInLinks = [
    { href: "/products/create", label: "Sell", icon: PlusSquare },
    { href: "/bookmarks", label: "Saved", icon: Bookmark },
    { href: "/messages", label: "Messages", icon: MessageCircle },
    { href: `/${username}`, label: "Profile", icon: User },
  ];

  const navLinks = user
    ? [...baseLinks, ...signedInLinks]
    : [...baseLinks, ...signedOutLinks];

  return (
    <>
      {/* Top bar */}
      <nav className="border-b border-gray-300 bg-white">
        <div className="max-w-7xl mx-auto flex items-center justify-between px-4 py-3">
          <Link href="/" className="shrink-0">
            <img src="/logo2.png" alt="SlugMarket" className="h-20 w-auto" />
          </Link>

          {/* Search bar — hidden below 945px */}
          <div className="hidden min-[945px]:block w-64">
            <NavSearchBar />
          </div>

          {/* Mobile-only top bar right side */}
          {user && (
            <div className="flex items-center gap-5 min-[770px]:hidden">
              <NotificationBell />
              <button
                type="button"
                onClick={handleSignOut}
                className="flex items-center text-gray-700 hover:text-blue-600 cursor-pointer"
              >
                <LogOut size={24} strokeWidth={2} />
              </button>
            </div>
          )}

          {/* Desktop nav links — hidden on mobile */}
          <div className="hidden min-[770px]:flex items-center gap-8">
            {navLinks.map((link) => {
              const Icon = link.icon;
              const isProfile = link.label === "Profile";
              const isMessage = link.label === "Messages"
              return (
                <Link
                  key={link.href}
                  href={link.href}
                  className={`relative flex flex-col items-center ${getLinkClasses(link.href)}`}
                >
                  {isMessage && hasUnreadMessages && (
                      <span className="absolute -top-1 -right-1 bg-red-500 text-xs rounded-full w-4 h-4 flex items-center justify-center" />   
                  )}
                  {isProfile && avatarUrl
                    ? <img src={avatarUrl} alt="avatar" className="w-6 h-6 rounded-full object-cover" />
                    : <Icon size={24} strokeWidth={2} />}
                </Link>
              );
            })}

            {user && <NotificationBell />}

            {user && (
              <button
                type="button"
                onClick={handleSignOut}
                className="flex flex-col items-center text-gray-700 hover:text-blue-600 cursor-pointer"
              >
                <LogOut size={24} strokeWidth={2} />
              </button>
            )}
          </div>
        </div>
      </nav>

      {/* Mobile bottom nav — visible only on small screens */}
      <nav className="min-[770px]:hidden fixed bottom-0 left-0 right-0 z-50 border-t border-gray-200 bg-white">
        <div className="flex items-center justify-around px-2 py-2">
          {navLinks.filter((link) => link.label !== "Saved").map((link) => {
            const Icon = link.icon;
            const isProfile = link.label === "Profile";
            return (
              <Link
                key={link.href}
                href={link.href}
                className={`flex flex-col items-center px-3 py-1 ${getLinkClasses(link.href)}`}
              >
                {isProfile && avatarUrl
                  ? <img src={avatarUrl} alt="avatar" className="w-6 h-6 rounded-full object-cover" />
                  : <Icon size={24} strokeWidth={2} />}
              </Link>
            );
          })}

        </div>
      </nav>
    </>
  );
}

"use client";
import { useState, useEffect, useRef } from "react"
import { Bell } from "lucide-react"
import Link from "next/link"
import { supabase } from "@/lib/supabase"
import { useAuth } from "./AuthProvider"
import type { Notification } from "@/lib/types";

// Notification bell component that shows unread count and a dropdown of notifications on click
export default function NotificationBell() {
    const { user } = useAuth()
    const [open, setOpen] = useState(false)
    const [notifications, setNotifications] = useState<Notification[]>([])

    // fetch notifications
    useEffect(() => {
        if (!user) return

        supabase
            .from("notifications")
            .select("*")
            .eq("user_id", user.id)
            .order("created_at", { ascending: false})
            .limit(10)
            .then(({ data}) => {
                if (data) setNotifications(data)
            })

        // adding new notificatons in real time
        const channel = supabase
            .channel(`notifications:${user.id}:${crypto.randomUUID()}`)
            .on(
                "postgres_changes",
                {
                    event: "INSERT",
                    schema: "public",
                    table: "notifications",
                },
                (payload) => {
                    setNotifications((prev) => [payload.new as Notification, ...prev])
                }
            )
            .subscribe()

        return () => { supabase.removeChannel(channel)}
    }, [user?.id])

    // mark all unread notifications as read when popup opens
    useEffect(() => {
        if (!open || !user) return
        const unreadIds = notifications
            .filter((n) => !n.read)
            .map((n) => n.id)
        if (unreadIds.length === 0) return

        supabase
            .from("notifications")
            .update({ read: true })
            .in("id", unreadIds)
            .then(() => {
                setNotifications((prev) =>
                    prev.map((n) => (unreadIds.includes(n.id) ? { ...n, read: true } : n))
                )
            })
    }, [open])

    if (!user) return null

    const unreadCount = notifications.filter(n => !n.read).length

    return (
        <div className="relative" onMouseLeave={() => setOpen(false)}>
            <button
                type="button"
                className="relative flex flex-col items-center text-gray-700 hover:text-blue-600 cursor-pointer"
                onClick={() => setOpen((o) => !o)}
                onMouseEnter={() => setOpen(true)}
            >
                <Bell size={24} />
                {unreadCount > 0 && (
                    <span className="absolute -top-1 -right-1 bg-red-500 text-white text-xs rounded-full w-4 h-4 flex items-center justify-center">
                        {unreadCount}
                    </span>
                )}
            </button>

            {/* Dropdown popup */}
            {open && (
                <div className="absolute right-0 mt-0 w-72 bg-white border border-gray-200 rounded-xl shadow-xl z-50 overflow-hidden">
                    {notifications.length === 0
                        ? <p className="p-4 text-sm text-gray-500">No notifications</p>
                        : notifications.map((n) => {
                            const inner = (
                                <>
                                    {n.image_url && (
                                        <img
                                            src={n.image_url}
                                            className="w-10 h-10 rounded-lg object-cover shrink-0"
                                        />
                                    )}
                                    <span>{n.message}</span>
                                </>
                            )
                            const cls = `flex items-center gap-3 px-4 py-3 text-sm border-b last:border-0 ${n.read ? "text-gray-500" : "font-semibold text-gray-800"}`

                            return n.link
                                ? <Link
                                    key={n.id}
                                    href={n.link}
                                    onClick={() => setOpen(false)}
                                    className={cls + " hover:bg-gray-50"}
                                  >
                                    {inner}
                                  </Link>
                                : <div key={n.id} className={cls}>{inner}</div>
                        })
                    }
                </div>
            )}
        </div>
    )
}

"use client"

import type { OfferDetails } from "@/lib/types"

type Props = {
    offer: OfferDetails
    isFromMe: boolean
    currentUserId: string
    onStatusChange: (offerId: string, status: "accepted" | "declined") => void
}

// Offers expire 48 hours after creation. This function calculates the expiry label and whether it's expired.
function getExpiryLabel(createdAt: string): { label: string; expired: boolean } {
    const expiresAt = new Date(new Date(createdAt).getTime() + 48 * 60 * 60 * 1000)
    const msLeft = expiresAt.getTime() - Date.now()
    if (msLeft <= 0) return { label: "Expired", expired: true }
    const hoursLeft = Math.floor(msLeft / (1000 * 60 * 60))
    if (hoursLeft < 1) return { label: "Expires in less than 1 hour", expired: false }
    if (hoursLeft < 24) return { label: `Expires in ${hoursLeft}h`, expired: false }
    return { label: `Expires in ${Math.floor(hoursLeft / 24)}d`, expired: false }
}

export default function OfferCard({ offer, isFromMe, currentUserId, onStatusChange }: Props) {
    const isSeller = currentUserId === offer.seller_id
    const isPending = offer.status === "pending"
    const { label: expiryLabel, expired } = getExpiryLabel(offer.created_at)
    const statusColor = offer.status === "accepted" ? "text-green-600" : "text-red-500"

    return (
        <div className={`w-64 rounded-2xl bg-white border border-gray-100 shadow-sm overflow-hidden ${isFromMe ? "self-end" : "self-start"}`}>
            {offer.listing && (
                <a href={`/products/${offer.listing.id}`} className="block">
                    <img src={offer.listing.image_urls[0]} alt={offer.listing.title} className="w-full h-32 object-cover" />
                </a>
            )}
            <div className="p-4">
                <div className="flex items-center justify-between mb-2">
                    <span className="rounded-full bg-[#F5C518]/25 px-2.5 py-0.5 text-xs font-semibold text-[#0F2044] uppercase tracking-wide">
                        Offer
                    </span>
                    {offer.status !== "pending" && (
                        <span className={`text-xs font-semibold capitalize ${statusColor}`}>{offer.status}</span>
                    )}
                    {isPending && (
                        <span className={`text-xs font-medium ${expired ? "text-red-400" : "text-gray-400"}`}>{expiryLabel}</span>
                    )}
                </div>
                {offer.listing && (
                    <a href={`/products/${offer.listing.id}`} className="text-sm font-medium text-gray-700 hover:underline line-clamp-2 block mb-2">
                        {offer.listing.title}
                    </a>
                )}
                <p className="text-2xl font-bold text-[#0F2044]">${Number(offer.amount).toLocaleString()}</p>
                {isSeller && isPending && !expired && (
                    <div className="flex gap-2 mt-3">
                        <button onClick={() => onStatusChange(offer.id, "accepted")} className="flex-1 rounded-xl bg-[#0F2044] py-2 text-sm font-semibold text-white hover:bg-[#162d5a] transition cursor-pointer">Accept</button>
                        <button onClick={() => onStatusChange(offer.id, "declined")} className="flex-1 rounded-xl bg-gray-100 py-2 text-sm font-semibold text-gray-600 hover:bg-gray-200 transition cursor-pointer">Decline</button>
                    </div>
                )}
            </div>
        </div>
    )
}

"use client";

import { useEffect, useState } from "react";
import { Bookmark, ChevronLeft, ChevronRight } from "lucide-react"
import { useAuth } from "./AuthProvider"
import { useRouter } from "next/navigation"
import { supabase } from "@/lib/supabase"

type ProductImageGalleryProps = {
  images: string[];
  title: string;
  product_id: string;
};

// This component renders a product image gallery with next/previous buttons and a bookmark toggle. 
// It also checks if the current user has bookmarked the product and allows toggling the bookmark state.
export default function ProductImageGallery({ images, title, product_id }: ProductImageGalleryProps) {
  const { user, loading: authLoading } = useAuth()
  const router = useRouter()
  const [currentIndex, setCurrentIndex] = useState(0)
  const [isBookmarkActive, setIsBookmarkActive] = useState(false)

  const currentImage = images[currentIndex]

  // Initial state of bookmark
  useEffect(() => {
    if (authLoading) return;

    if (!user) {
      setIsBookmarkActive(false);
      return;
    }

    // when loading is finished and user is actually logged in
    let cancelled = false;

    async function checkBookmarkExists() {
      const { data, error } = await supabase
        .from("bookmarks")
        .select("product_id")
        .eq("user_id", user?.id)
        .eq("product_id", product_id)
        .maybeSingle();

      if (!cancelled && !error && data) setIsBookmarkActive(true);
    };

    checkBookmarkExists()

    return () => {
      cancelled = true;
    }
  }, [authLoading, user, product_id])

  // Toggle bookmark state and update database accordingly
  async function toggleBookmark() {
    if (authLoading) return;
    if (!user) {
      router.push(`/signin?next=/products/${encodeURIComponent(product_id)}`)
      return
    }

    const nextState = !isBookmarkActive
    setIsBookmarkActive(nextState)

    if (nextState) {
      const { error } = await supabase.from("bookmarks").insert({
        user_id: user?.id,
        product_id
      })

      if (error) {
        setIsBookmarkActive(false)
        console.error(error)
      }
    } else {
      const { error } = await supabase.from("bookmarks").delete().eq("user_id", user?.id).eq("product_id", product_id)

      if (error) {
        setIsBookmarkActive(true)
        console.error(error)
      }
    }
  }

  // Handlers for next and previous buttons with wrap-around logic
  function goPrevious() {
    setCurrentIndex((prev) => (prev === 0 ? images.length - 1 : prev - 1));
  }

  function goNext() {
    setCurrentIndex((prev) => (prev === images.length - 1 ? 0 : prev + 1));
  }

  return (
    <div className="w-full">
      <div className="relative overflow-hidden rounded-lg bg-gray-100">
        <img
          src={currentImage}
          alt={title}
          className="aspect-square w-full object-cover"
        />

        {/* Bookmark Button */}
        <div className="absolute right-4 top-4 flex flex-col gap-3">
          <button
            type="button"
            onClick={toggleBookmark}
            className="rounded-full bg-black/20 p-3 backdrop-blur-sm transition hover:bg-black/30 hover:scale-105 cursor-pointer"
            aria-label="Toggle bookmark"
          >
            <Bookmark className={`h-6 w-6 transition ${isBookmarkActive ? "fill-red-500 text-red-500" : "text-white"}`} />
          </button>

        </div>

        {/* prev and next buttons */}
        {images.length > 1 && (
          <>
            <button
              onClick={goPrevious}
              className="absolute left-3 top-1/2 -translate-y-1/2 bg-black/30 hover:bg-black/50 text-white rounded-full w-9 h-9 flex items-center justify-center transition backdrop-blur-sm cursor-pointer"
            >
              <ChevronLeft size={20} strokeWidth={2.5} />
            </button>

            <button
              onClick={goNext}
              className="absolute right-3 top-1/2 -translate-y-1/2 bg-black/30 hover:bg-black/50 text-white rounded-full w-9 h-9 flex items-center justify-center transition backdrop-blur-sm cursor-pointer"
            >
              <ChevronRight size={20} strokeWidth={2.5} />
            </button>
          </>
        )}
      </div>

      {images.length > 1 && (
        <p className="mt-3 text-sm text-gray-600">
          {currentIndex + 1} / {images.length}
        </p>
      )}
    </div>
  );
}

"use client"

import React, { useEffect, useState } from "react"
import { useRouter } from "next/navigation"
import { supabase } from "@/lib/supabase"
import { useAuth } from "./AuthProvider"
import { revalidateListings } from "@/app/actions/listings"
import { CONDITIONS, CATEGORIES, type ListingForm, type ListingImage, type LocalImage } from "@/lib/types"
import { uploadLocals } from "@/lib/uploadImages"
import ImageUploadGrid from "./ImageUploadGrid"
import Dropdown from "./Dropdown"

const inputCls = "w-full border border-gray-300 rounded-lg px-4 py-2.5 text-gray-900 focus:outline-none focus:ring-2 focus:ring-[#0F2044] focus:border-transparent"

function Field({ label, htmlFor, children }: { label: string; htmlFor: string; children: React.ReactNode }) {
    return (
        <div>
            <label htmlFor={htmlFor} className="block text-sm font-medium text-gray-700 mb-1">{label}</label>
            {children}
        </div>
    )
}

export type ProductListingFormProps = {
    mode: "create" | "edit"
    listingId?: string
    initialForm?: ListingForm
    initialImageUrls?: string[]
}

export default function ProductListingForm({ mode, listingId, initialForm, initialImageUrls = [] }: ProductListingFormProps) {
    const { user, loading } = useAuth()
    const router = useRouter()

    useEffect(() => {
        if (!loading && !user) router.replace("/signin")
    }, [loading, user, router])

    const [form, setForm] = useState<ListingForm>({
        title: initialForm?.title ?? "",
        price: initialForm?.price ?? "",
        description: initialForm?.description ?? "",
        condition: initialForm?.condition ?? "",
        category: initialForm?.category ?? "",
    })
    const [images, setImages] = useState<ListingImage[]>(
        initialImageUrls.map((url) => ({ kind: "remote", url }))
    )
    const [loadingSubmit, setLoadingSubmit] = useState(false)
    const [error, setError] = useState<string | null>(null)

    function handleChange(e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) {
        setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }))
    }

    function addImages(files: File[]) {
        const next: LocalImage[] = files.map((file) => ({ kind: "local", file, url: URL.createObjectURL(file) }))
        setImages((prev) => [...prev, ...next])
    }

    function removeImage(index: number) {
        setImages((prev) => {
            const removed = prev[index]
            if (removed?.kind === "local") URL.revokeObjectURL(removed.url)
            const copy = prev.slice()
            copy.splice(index, 1)
            return copy
        })
    }

    async function handleSubmit(e: React.FormEvent) {
        e.preventDefault()
        if (!user) { router.replace("/signin"); return }
        if (images.length === 0) { setError("Please add at least one photo"); return }
        if (mode === "edit" && !listingId) { setError("Missing listing id"); return }

        setLoadingSubmit(true)
        setError(null)

        try {
            const remoteUrls = images.filter((img) => img.kind === "remote").map((img) => img.url)
            const localFiles = images.flatMap((img): File[] => img.kind === "local" ? [(img as LocalImage).file] : [])
            const image_urls = [...remoteUrls, ...await uploadLocals(localFiles, user.id)]
            const row = { title: form.title, price: parseFloat(form.price), description: form.description, condition: form.condition, 
                category: form.category, image_urls }

            if (mode === "create") {
                const { data: inserted, error: insertError } = await supabase
                    .from("product_listings").insert({ ...row, seller_id: user.id }).select("id").single()
                if (insertError) throw new Error(insertError.message)
                await revalidateListings()
                router.push(`/products/${inserted.id}`)
            } else {
                const { error: updateError } = await supabase
                    .from("product_listings").update(row).eq("id", listingId).eq("seller_id", user.id)
                if (updateError) throw new Error(updateError.message)
                await revalidateListings()
                router.push(`/products/${listingId}`)
            }
        } catch (err: unknown) {
            setError(err instanceof Error ? err.message : "Something went wrong.")
        } finally {
            setLoadingSubmit(false)
        }
    }

    if (loading || !user) return null

    const heading = mode === "create" ? "Post a Listing" : "Edit Listing"
    const subtitle = mode === "create" ? "Fill in the details about what you're selling." : "Update your listing details."
    const submitLabel = mode === "create" ? (loadingSubmit ? "Posting..." : "Post Listing") : (loadingSubmit ? "Saving..." : "Save changes")

    return (
        <main className="max-w-2xl mx-auto px-6 py-12">
            <h1 className="text-3xl font-bold text-gray-900 mb-2">{heading}</h1>
            <p className="text-gray-500 mb-8">{subtitle}</p>
            <form onSubmit={handleSubmit} className="space-y-6">
                <Field label="Title" htmlFor="title">
                    <input id="title" name="title" type="text" required value={form.title} onChange={handleChange} placeholder="e.g. Calculus Textbook 9th Edition" className={inputCls} />
                </Field>
                <Field label="Price" htmlFor="price">
                    <div className="relative">
                        <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400 font-medium">$</span>
                        <input id="price" name="price" type="number" required min="0" step="0.01" value={form.price} onChange={handleChange} placeholder="0.00" className={`${inputCls} pl-8`} />
                    </div>
                </Field>
                <Field label="Description" htmlFor="description">
                    <textarea id="description" name="description" required rows={4} value={form.description} onChange={handleChange} placeholder="Describe your item — include any relevant details like edition, size, color, etc." className={`${inputCls} resize-none`} />
                </Field>
                <div>
                    <label id="condition-label" className="block text-sm font-medium text-gray-700 mb-1">Condition</label>
                    <Dropdown
                        value={form.condition}
                        onSelect={(v) => setForm((prev) => ({ ...prev, condition: v as ListingForm["condition"] }))}
                        placeholder="Select a condition…"
                        ariaLabelledby="condition-label"
                        triggerClassName="w-full flex items-center justify-between rounded-lg border border-gray-300 px-4 py-2.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-[#0F2044] focus:border-transparent transition cursor-pointer"
                        options={CONDITIONS.map((c) => ({ value: c, label: c }))}
                    />
                </div>
                <div>
                    <label id="category-label" className="block text-sm font-medium text-gray-700 mb-1">Category</label>
                    <Dropdown
                        value={form.category}
                        onSelect={(v) => setForm((prev) => ({ ...prev, category: v as ListingForm["category"] }))}
                        placeholder="Select a category…"
                        ariaLabelledby="category-label"
                        triggerClassName="w-full flex items-center justify-between rounded-lg border border-gray-300 px-4 py-2.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-[#0F2044] focus:border-transparent transition cursor-pointer"
                        options={CATEGORIES.map((cat) => ({ value: cat, label: cat }))}
                    />
                </div>

                <ImageUploadGrid images={images} onAdd={addImages} onRemove={removeImage} />
                {error && <p className="text-red-500 text-sm">{error}</p>}
                <button type="submit" disabled={loadingSubmit} className="w-full bg-yellow-400 hover:bg-yellow-500 disabled:opacity-50 text-gray-900 font-semibold py-3 rounded-lg transition-colors text-base cursor-pointer">
                    {submitLabel}
                </button>
            </form>
        </main>
    )
}

"use client";

import { useState } from "react";
import ListingCard from "./ListingCard";
import { Listing } from "@/lib/types";
import { useAuth } from "./AuthProvider";
import { fetchBookmarkedProducts } from "@/lib/fetchProducts";
import ListingManageModal from "./ListingManageModal"
import ReviewsSection from "./ReviewsSection";

type Props = {
  listings: Listing[];
  soldListings: Listing[];
  profileId: string;
  buyerUsernames?: Record<string, string>;
};

// This component renders the profile tabs for a user's profile page, including active listings, sold listings, and bookmarks (if it's the user's own profile). 
// It manages the active tab state and fetches bookmarked products when the bookmarks tab is selected for the first time. 
// It also handles loading states and displays appropriate messages when there are no listings or bookmarks.
export default function ProfileTabs({ listings, soldListings, profileId, buyerUsernames = {} }: Props) {
  const { user } = useAuth();
  const isOwnProfile = !!user && user.id === profileId;
  const [activeTab, setActiveTab] = useState<"active" | "sold" | "bookmarks" | "reviews">("active");
  const [bookmarks, setBookmarks] = useState<Listing[]>([]);
  const [bookmarksLoaded, setBookmarksLoaded] = useState(false);
  const [bookmarksLoading, setBookmarksLoading] = useState(false);
  const [selectedListing, setSelectedListing] = useState<Listing | null>(null)

  async function handleBookmarksTab() {
    setActiveTab("bookmarks");
    if (!bookmarksLoaded) {
      setBookmarksLoading(true);
      const data = await fetchBookmarkedProducts(profileId);
      setBookmarks(data as Listing[]);
      setBookmarksLoaded(true);
      setBookmarksLoading(false);
    }
  }

  return (
    <div>
      {/* Tab buttons */}
      <div className="flex overflow-x-auto border-b border-gray-200 mb-6 scrollbar-none">
        <button
          onClick={() => setActiveTab("active")}
          className={`shrink-0 px-6 py-2 text-sm font-medium transition-colors cursor-pointer ${
            activeTab === "active"
              ? "border-b-2 border-gray-900 text-gray-900"
              : "text-gray-400 hover:text-gray-600"
          }`}
        >
          Listings
          {listings.length > 0 && (
            <span className="ml-2 rounded-full bg-gray-100 px-2 py-0.5 text-xs text-gray-600">
              {listings.length}
            </span>
          )}
        </button>
        <button
          onClick={() => setActiveTab("sold")}
          className={`shrink-0 px-6 py-2 text-sm font-medium transition-colors cursor-pointer ${
            activeTab === "sold"
              ? "border-b-2 border-gray-900 text-gray-900"
              : "text-gray-400 hover:text-gray-600"
          }`}
        >
          Sold
          {soldListings.length > 0 && (
            <span className="ml-2 rounded-full bg-gray-100 px-2 py-0.5 text-xs text-gray-600">
              {soldListings.length}
            </span>
          )}
        </button>
        <button
          onClick={() => setActiveTab("reviews")}
          className={`shrink-0 px-6 py-2 text-sm font-medium transition-colors cursor-pointer ${
            activeTab === "reviews"
              ? "border-b-2 border-gray-900 text-gray-900"
              : "text-gray-400 hover:text-gray-600"
          }`}
        >
          Reviews
        </button>


        {/* Saved tab — mobile only, own profile only */}
        {isOwnProfile && (
          <button
            onClick={handleBookmarksTab}
            className={`shrink-0 min-[770px]:hidden px-6 py-2 text-sm font-medium transition-colors cursor-pointer ${
              activeTab === "bookmarks"
                ? "border-b-2 border-gray-900 text-gray-900"
                : "text-gray-400 hover:text-gray-600"
            }`}
          >
            Saved
          </button>
        )}
      </div>

      {/* Tab content */}
      {activeTab === "bookmarks" ? (
        bookmarksLoading ? (
          <p className="text-gray-400 italic">Loading...</p>
        ) : bookmarks.length === 0 ? (
          <p className="text-gray-400 italic">No saved items.</p>
        ) : (
          <div className="grid grid-cols-1 min-[770px]:grid-cols-2 lg:grid-cols-3 gap-4">
            {bookmarks.map((listing) => (
              <ListingCard key={listing.id} listing={listing} />
            ))}
          </div>
        )
      ) : activeTab === "active" ? (
        listings.length === 0 ? (
          <p className="text-gray-400 italic">No active listings.</p>
        ) : (
          <div className="grid grid-cols-1 min-[770px]:grid-cols-2 lg:grid-cols-3 gap-4">
            {listings.map((listing) => (
              <ListingCard
                key={listing.id}
                listing={listing} 
                onSelectListing={isOwnProfile ? () => setSelectedListing(listing) : undefined}
              />
            ))}
          </div>
        )
      ) : activeTab === "reviews" ? (
          <ReviewsSection profileId={profileId} />
      ) : soldListings.length === 0 ? (
          <p className="text-gray-400 italic">No sold listings.</p>
      ) : (
        <div className="grid grid-cols-1 min-[770px]:grid-cols-2 lg:grid-cols-3 gap-4">
          {soldListings.map((listing) => {
            const buyer = listing.buyer_id ? buyerUsernames[listing.buyer_id] : undefined;
            return (
              <div key={listing.id} className="flex flex-col gap-1">
                <div className="relative opacity-60">
                  <ListingCard listing={listing} />
                </div>
                {buyer && (
                  <p className="text-xs text-gray-500 text-center">
                    Sold to{" "}
                    <a href={`/${buyer}`} className="font-medium text-gray-700 hover:underline">
                      @{buyer}
                    </a>
                  </p>
                )}
              </div>
            );
          })}
        </div>
      )}

      {selectedListing && isOwnProfile && (
        <ListingManageModal listing={selectedListing} onClose={() => setSelectedListing(null)} />
      )}
    </div>
  );
}

"use client";

import { Flag } from "lucide-react";
import { useState } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "@/lib/supabase";
import { useAuth } from "./AuthProvider";
import Dropdown from "./Dropdown";

type Props = { listingId: string; sellerId: string; className?: string };

const REASONS = [
    "Prohibited or illegal item",
    "Spam or scam",
    "Inappropriate content",
    "Misleading or fake listing",
    "Other",
];

// ReportButton lets a user flag a listing. It opens a modal with a reason
// dropdown plus an optional details field, and inserts a row into the `reports`
// table. Hidden from the listing's own seller.
export default function ReportButton({ listingId, sellerId, className }: Props) {
    const { user } = useAuth();
    const router = useRouter();
    const [open, setOpen] = useState(false);
    const [reason, setReason] = useState(REASONS[0]);
    const [details, setDetails] = useState("");
    const [submitted, setSubmitted] = useState(false);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    if (user?.id === sellerId) return null;

    function handleClose() {
        setOpen(false); setSubmitted(false); setReason(REASONS[0]); setDetails(""); setError(null);
    }

    async function handleSubmit(e: { preventDefault(): void }) {
        e.preventDefault();
        if (!user) { router.push("/signin"); return; }
        setLoading(true);
        setError(null);
        try {
            const { error: insertError } = await supabase.from("reports").insert({
                listing_id: listingId,
                seller_id: sellerId,
                reporter_id: user.id,
                reason,
                details: details.trim() || null,
            });
            if (insertError) throw insertError;
            setSubmitted(true);
        } catch (err: unknown) {
            const message =
                err instanceof Error ? err.message
                : typeof err === "object" && err !== null && "message" in err
                    ? String((err as { message: unknown }).message)
                : null;
            setError(message || "Something went wrong. Please try again.");
        } finally {
            setLoading(false);
        }
    }

    return (
        <>
            <button
                onClick={() => { if (!user) { router.push("/signin"); return; } setOpen(true); }}
                className={className ?? "flex items-center gap-2 rounded-lg bg-gray-100 px-4 py-2 text-sm font-medium text-gray-500 hover:bg-red-50 hover:text-red-500 transition cursor-pointer"}
            >
                <Flag size={15} />
                Report
            </button>

            {open && (
                <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
                    <div className="bg-white rounded-2xl shadow-xl w-full max-w-md mx-4 p-6">
                        {submitted ? (
                            <div className="flex flex-col items-center gap-4 py-4">
                                <div className="text-4xl">✓</div>
                                <p className="text-xl font-semibold text-gray-900">Report submitted</p>
                                <p className="text-gray-500 text-center">Thanks for helping keep SlugMarket safe. Our team will review this listing.</p>
                                <button onClick={handleClose} className="mt-2 w-full rounded-xl bg-[#0F2044] py-3 text-lg font-semibold text-white hover:bg-[#162d5a] transition cursor-pointer">Done</button>
                            </div>
                        ) : (
                            <form onSubmit={handleSubmit} className="flex flex-col gap-4">
                                <div className="flex items-center justify-between">
                                    <h2 className="text-2xl font-bold text-gray-900">Report listing</h2>
                                    <button type="button" onClick={handleClose} className="text-gray-400 hover:text-gray-600 text-2xl leading-none cursor-pointer">&times;</button>
                                </div>
                                <div className="flex flex-col gap-1 text-sm font-medium text-gray-700">
                                    Reason
                                    <Dropdown
                                        value={reason}
                                        onSelect={setReason}
                                        triggerClassName="w-full flex items-center justify-between rounded-lg border border-gray-300 px-4 py-2.5 text-sm bg-white focus:outline-none focus:ring-2 focus:ring-[#0F2044] focus:border-transparent transition cursor-pointer"
                                        options={REASONS.map((r) => ({ value: r, label: r }))}
                                    />
                                </div>
                                <label className="flex flex-col gap-1 text-sm font-medium text-gray-700">
                                    Details <span className="font-normal text-gray-400">(optional)</span>
                                    <textarea value={details} onChange={(e) => setDetails(e.target.value)} rows={4} maxLength={1000} placeholder="Add any additional context…" className="w-full rounded-xl border-2 border-gray-200 py-3 px-4 text-base resize-none focus:border-[#0F2044] focus:outline-none" />
                                </label>
                                {error && <p className="text-red-500 text-sm">{error}</p>}
                                <button type="submit" disabled={loading} className="w-full rounded-xl bg-[#F5C518] py-3 text-lg font-semibold text-[#0F2044] hover:bg-[#fde047] transition disabled:opacity-50 cursor-pointer">{loading ? "Submitting…" : "Submit report"}</button>
                            </form>
                        )}
                    </div>
                </div>
            )}
        </>
    );
}

"use client";

import { useEffect, useState } from "react";
import { supabase } from "@/lib/supabase";

export default function ReviewsSection({ profileId }: { profileId: string }) {
  const [reviews, setReviews] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function load() {
      //
      // 1. Fetch reviews for this profile
      //
      const { data: reviewRows, error: reviewError } = await supabase
        .from("reviews")
        .select("*")
        .eq("reviewed_user_id", profileId)
        .order("created_at", { ascending: false });

      if (reviewError) {
        console.error("Review fetch error:", reviewError);
        setLoading(false);
        return;
      }

      if (!reviewRows || reviewRows.length === 0) {
        setReviews([]);
        setLoading(false);
        return;
      }

      //
      // 2. Extract reviewer_ids
      //
      const reviewerIds = reviewRows.map((r) => r.reviewer_id);

      //
      // 3. Fetch profiles for those reviewers
      //
      const { data: profileRows, error: profileError } = await supabase
        .from("profiles")
        .select("id, username, avatar_url")
        .in("id", reviewerIds);

      if (profileError) {
        console.error("Profile fetch error:", profileError);
        setLoading(false);
        return;
      }

      //
      // 4. Map profiles by id
      //
      const profileMap = Object.fromEntries(
        profileRows.map((p) => [p.id, p])
      );

      //
      // 5. Merge reviews with reviewer profile info
      //
      const merged = reviewRows.map((r) => ({
        ...r,
        reviewer: profileMap[r.reviewer_id] || null,
      }));

      setReviews(merged);
      setLoading(false);
    }

    load();

    function handleRefresh(e: Event) {
      const { profileId: id } = (e as CustomEvent).detail
      if (id === profileId) load()
    }

    window.addEventListener("review-submitted", handleRefresh)
    return () => window.removeEventListener("review-submitted", handleRefresh)
  }, [profileId]);

  if (loading) {
    return <p className="text-gray-400 italic">Loading reviews…</p>;
  }

  if (reviews.length === 0) {
    return <p className="text-gray-400 italic">No reviews yet.</p>;
  }

  return (
    <div className="space-y-4">
      {reviews.map((r) => (
        <div
          key={r.review_id}
          className="border p-4 rounded-lg shadow-sm"
        >
          <div className="flex items-center gap-2 mb-1">
            <p className="font-semibold">
              @{r.reviewer?.username || "Unknown"}
            </p>
            <span className="text-yellow-500">⭐ {r.rating}</span>
          </div>

          <p className="text-gray-700 break-words">{r.review_text}</p>

          <p className="text-xs text-gray-400 mt-1">
            {new Date(r.created_at).toLocaleDateString()}
          </p>

          {r.listing_id && (
            <p className="text-xs text-gray-500 mt-1">
              Related listing:{" "}
              <a
                href={`/products/${r.listing_id}`}
                className="underline hover:text-gray-700"
              >
                View
              </a>
            </p>
          )}
        </div>
      ))}
    </div>
  );
}

"use client";

import { Share2, Check } from "lucide-react";
import { useState } from "react";

// ShareButton lets a user share a listing. On devices that support the Web Share
// API (mostly mobile) it opens the native share sheet; otherwise it copies the
// listing URL to the clipboard and briefly shows a "Copied!" confirmation.
export default function ShareButton({ title, className }: { title: string; className?: string }) {
    const [copied, setCopied] = useState(false);

    async function handleShare() {
        const url = window.location.href;

        if (navigator.share) {
            try {
                await navigator.share({ title, url });
                return;
            } catch {
                // User cancelled the share sheet, or it failed — fall through to copy.
            }
        }

        try {
            await navigator.clipboard.writeText(url);
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        } catch {
            // Clipboard unavailable (e.g. insecure context) — nothing more we can do.
        }
    }

    return (
        <button onClick={handleShare} className={className}>
            {copied ? <Check size={16} /> : <Share2 size={16} />}
            {copied ? "Copied!" : "Share"}
        </button>
    );
}

