const h = vi.hoisted(() => ({
  mockPush: vi.fn(),
  state: {
    responses: {} as Record<string, unknown>,
    inserts: [] as Array<{ table: string; values: Record<string, unknown> }>,
  },
}));

vi.mock("next/navigation", () => ({
