// Helper function to fetch bookmarked products for a user
export async function fetchBookmarkedProducts(userId: string) {
  const { data: bookmarks, error: bookmarkError } = await supabase
    .from("bookmarks")
    .select("product_id")
    .eq("user_id", userId);

  if (bookmarkError) {
    console.error("Supabase bookmark error:", bookmarkError);
    throw new Error(bookmarkError.message);
  }

  const productIds = bookmarks?.map((bookmark) => bookmark.product_id) ?? [];

  if (productIds.length === 0) {
    return [];
  }

  const { data: products, error: productError } = await supabase
    .from("product_listings")
    .select("*")
    .in("id", productIds);

  if (productError) {
    console.error("Supabase product error:", productError);
    throw new Error(productError.message);
  }

  return products ?? [];
}

// Helper function to fetch products by search query for search results page
export async function fetchProductByQuery(query: string) {
  const q = query.trim()
  if (!q) return []

  const { data, error } = await supabase
    .from("product_listings")
    .select("*")
    .eq("sold", false)
    .or(`title.ilike.%${q}%,description.ilike.%${q}%`)
    .order("created_at", { ascending: false})

    if (error) {
      console.error("Supabase error:", error)
      throw new Error(error.message)
    }

    return data ?? []
}

